import toast from 'react-hot-toast';
import { apiConnector } from '../apiconnector';
import { catalogData } from '../api';

export const getCatalogPageData = async(categoryId) => {
  const toastId = toast.loading("Loading...");
  try {
    if (!categoryId) {
      throw new Error("Category ID is required");
    }

    const response = await apiConnector("POST", catalogData.CATALOGPAGEDATA_API, {
      categoryId: categoryId,
    });

    if (!response?.data?.success) {
      throw new Error(response?.data?.message || "Could not fetch category page data");
    }

    toast.dismiss(toastId);
    return response.data;
  } catch (error) {
    console.error("CATALOG PAGE API ERROR:", error);
    toast.error(error.message || "Failed to fetch catalog data");
    toast.dismiss(toastId);
    return {
      success: false,
      message: error.message || "Failed to fetch catalog data"
    };
  }
}
